<script lang="ts">
 import StudyToolCard from '$lib/components/chat/tool-results/StudyToolCard.svelte';
 import gallery from '$lib/fixtures/research-gallery.json';
 import type { ExploratoryOutputPage } from '$lib/api';
 import type { HarnessJobStatus } from '$lib/types';
 import type { PageReader } from '$lib/research/resources';
 import type { StudyRecommendations } from '$lib/research/recommendations';
 import { metrics, rows, source } from './snapshot';
 let family=$state('wavelets');let mode=$state('views');const completion={value:false};
 function changeMode(value:string){completion.value=false;mode=value;}
 const families=['wavelets','seasonality','events','regimes','predictive_signals','liquidity','parameters','falsification','learned_models'];
 const title=$derived(family==='snapshot'?'Captured MSFT study':family.replaceAll('_',' '));
 const longBinding={id:'long_signal',output:'long_signal',fields:[{name:'id',label:'Observation',description:'Synthetic observation field.',field_type:'string',unit:null},{name:'time',label:'Time',description:'Synthetic time field.',field_type:'number',unit:'samples'},{name:'group',label:'Group',description:'Synthetic group field.',field_type:'string',unit:null},{name:'value',label:'Value',description:'Synthetic value field.',field_type:'number',unit:null}],identity:'id',selection_group:null,event_time:null,available_at:null};
 const longPanel={id:'signal',kind:'line',title:'Long signal',dataset:'long_signal',encodings:{x:'time',y:'value'},description:null};
 const longOutputs={long_signal:{kind:'table',columns:['id','time','group','value'],rows:Array.from({length:5100},(_,i)=>[`row-${i}`,i,i%17===0?null:'sample',i===5?null:Math.sin(i/20)])},description:{kind:'dataset_semantics',semantics:{schema_version:1,dataset:longBinding,row_meaning:'One synthetic signal observation per sample',grain:['id'],dimensions:['time','group'],measures:['value'],ordered:['time'],preferred_views:[longPanel]}}};
 const longArtifact={schema_version:1,job_id:'sdk-research-demonstration',programs:{long_preview:longOutputs}};
 const capture={schema_version:1,job_id:source.job,programs:{[source.program]:{[source.output]:{kind:'table',columns:Object.keys(rows[0]),rows:rows.map(row=>Object.values(row))}}}};
 const exportUrl=$derived(`data:application/json;charset=utf-8,${encodeURIComponent(JSON.stringify(family==='snapshot'?capture:family==='long_preview'?longArtifact:gallery.artifact))}`);
 const reader=$derived.by(()=>{
  const chosen=family;const state=mode;
  const read:PageReader=async(job,instance,name,offset=0)=>{
   if(chosen==='long_preview') {
    const identity={job_id:job,artifactName:'exploratory_outputs.json',artifactSha256:'0'.repeat(64)};
    if(!name)return {...identity,outputs:[{instanceId:'long_preview',name:'long_signal',kind:'table',count:5100},{instanceId:'long_preview',name:'description',kind:'dataset_semantics',count:null}],total:2,nextOffset:null} as ExploratoryOutputPage;
    const output=name==='description'?longOutputs.description:{...longOutputs.long_signal,rows:longOutputs.long_signal.rows.slice(offset,offset+100)};
    return {...identity,instanceId:instance,name,output,total:name==='description'?undefined:5100,nextOffset:name==='description'||offset+100>=5100?null:offset+100} as ExploratoryOutputPage;
   }
   if(chosen==='snapshot')return !name?{job_id:job,artifactName:'exploratory_outputs.json',artifactSha256:'0'.repeat(64),outputs:[{instanceId:source.program,name:source.output,kind:'table',count:rows.length}],total:1,nextOffset:null}:{job_id:job,artifactName:'exploratory_outputs.json',artifactSha256:'0'.repeat(64),instanceId:source.program,name,output:capture.programs[source.program][source.output],total:rows.length,nextOffset:null} as ExploratoryOutputPage;
   if(!name)return {...gallery.catalog,outputs:gallery.catalog.outputs.filter(o=>o.instanceId===chosen&&(!['data','suggestions'].includes(state)||o.kind!=='research_view'))} as ExploratoryOutputPage;
   const page=(gallery.pages as Record<string,unknown>)[`${instance}/${name}/${offset}`];if(!page)throw new Error('Demo output missing');return page as ExploratoryOutputPage;
  };return read;
 });
 const recommendationReader=$derived(mode==='suggestions'&&families.includes(family)?async (_job:string)=>({...gallery.recommendations,datasets:gallery.recommendations.datasets.filter(d=>d.instanceId===family)}) as StudyRecommendations:undefined);
 const jobReader=$derived.by(()=>{
  const state=mode;const started=new Date().toISOString();return async(job:string):Promise<HarnessJobStatus>=>({job_id:job,state:state==='running'&&!completion.value?'running':state==='failed'?'failed':state==='cancelled'?'cancelled':'succeeded',created_at:started,updated_at:new Date().toISOString(),progress:[],error_message:state==='failed'?'Demonstration output publication failed':null});
 });
</script>
<main>
 <header class="lab"><div><small>CONVERSATION DESIGN LAB</small><h1>A study, in the flow.</h1><p>The same study components used in live chat. Synthetic examples submit no jobs.</p></div><span>Shared production renderer</span></header>
 <nav class="scenarios" aria-label="Demo scenarios">{#each [['views','With research views'],['data','Returned data only'],['suggestions','Suggested views'],['running','Running'],['failed','Failed'],['cancelled','Cancelled']] as [value,label]}<button class:chosen={mode===value} onclick={()=>changeMode(value)}>{label}</button>{/each}<label>Study example<select aria-label="Study example" bind:value={family} onchange={()=>changeMode('views')}><option value="snapshot">Captured MSFT study</option><option value="long_preview">Bounded data preview · synthetic</option>{#each families as item}<option value={item}>{item.replaceAll('_',' ')} · synthetic</option>{/each}</select></label>{#if mode==='running'}<button onclick={()=>completion.value=true}>Finish preview</button>{/if}</nav>
 <div class="layout"><section class="conversation" aria-label="Study conversation preview"><div class="conversation-heading">Research conversation <small>{title} · preview</small></div><div class="transcript"><div class="user-message">Show me the {title} evidence and the observations behind it.</div><p>Each research view is available below, together with its source observations.</p><div class="activity">▤ Read study context <small>1 source</small></div><div class="study-activity"><span class:failed={mode==='failed'}></span>{#key `${family}:${mode}`}<StudyToolCard workspaceId="" {reader} {recommendationReader} {jobReader} {exportUrl} result={{tool:['running','failed','cancelled'].includes(mode)?'run_study':'read_study_output',ok:true,summary:'Study evidence',structured:{job_id:family==='snapshot'?source.job:'sdk-research-demonstration',programId:title,metrics:family==='snapshot'?metrics:undefined}}}/>{/key}</div><p class="followup">Inspect a chart mark, change a compatible mapping, or open Returned data for exact values.</p></div></section><aside><small>THE PRODUCTION CONTRACT</small><h2>Evidence, without the wall of cards.</h2><ol><li><b>Status becomes the result.</b><p>One study card owns its execution header and research tabs.</p></li><li><b>Meaningful field choices.</b><p>SDK dataset semantics declare roles and preferred views independently of research exhibits.</p></li><li><b>Explicit coverage.</b><p>Filters and mapping checks apply to loaded observations. Export retains complete evidence.</p></li><li><b>Extensible by registration.</b><p>Renderers own mapping policies. Tools publish data and descriptions.</p></li></ol><p class="note">The nine SDK examples are synthetic. The MSFT snapshot contains captured observations and receipt metrics, without invented research descriptors.</p></aside></div>
</main>
