(--border);margin-left:7px;padding-left:23px;min-width:0}.study-activity>span{position:absolute;left:-4px;top:24px;background:var(--color-accent);width:7px;height:7px;border-radius:50%;box-shadow:0 0 0 4px white}.study-activity>span.failed{background:var(--color-loss)}.followup{margin-left:31px!important}aside{padding-top:23px}aside h2{font-size:21px;font-weight:500;line-height:1.35;margin:12px 0 24px;letter-spacing:-.6px}ol{padding:0;list-style:none}li{margin-bottom:22px}li b{font-size:12px;font-weight:550}li p,.note{font-size:11px;color:var(--color-slate-400);line-height:1.7;margin-top:6px}.note{font-size:10px;border-top:1px solid var(--border);padding-top:18px}@media(max-width:1000px){main{padding:28px 24px}.layout{gap:24px;grid-template-columns:minmax(0,1fr) 210px}.transcript{padding:22px 18px}}@media(max-width:760px){main{padding:24px 12px}.lab{display:block}.layout{display:block}.scenarios label{margin-left:0;flex-basis:100%;margin-top:8px}.transcript{padding:20px 12px}.study-activity{padding-left:15px}.user-message{margin-left:8%}aside{max-width:460px;margin:24px auto}.followup{margin-left:23px!important}}
